command:
$ErrorActionPreference = 'Stop'
$workspace = 'D:\GitHub\Forge-Conductor-Windows-Edition'
. (Join-Path $workspace '.forge-codex\instructions\scripts\Common.ps1')
$evidencePath = Join-Path $workspace '.forge-codex\state\evidence\P16\manager-startup-policy-checkpoint.json'
$evidence = Get-Content -Raw -LiteralPath $evidencePath | ConvertFrom-Json
$sourceCount = 0
foreach ($property in $evidence.source_sha256.PSObject.Properties) {
    $actual = Get-FileSha256 -Path (Join-Path $workspace $property.Name)
    if ($actual -ne [string]$property.Value) {
        throw "Source hash mismatch: $($property.Name)"
    }
    $sourceCount++
}
$binaryPaths = [ordered]@{
    'ForgeConductor.Manager.StartupTests.exe' = 'out\build\windows-msvc-x64\bin\Debug\ForgeConductor.Manager.StartupTests.exe'
    'ForgeConductor.Manager.Startup.lib' = 'out\build\windows-msvc-x64\lib\Debug\ForgeConductor.Manager.Startup.lib'
    'ForgeConductor.Domain.lib' = 'out\build\windows-msvc-x64\lib\Debug\ForgeConductor.Domain.lib'
    'ForgeConductor.Contracts.HeaderSelfContainment.exe' = 'out\build\windows-msvc-x64\bin\Debug\ForgeConductor.Contracts.HeaderSelfContainment.exe'
}
$binaryCount = 0
foreach ($entry in $binaryPaths.GetEnumerator()) {
    $actual = Get-FileSha256 -Path (Join-Path $workspace $entry.Value)
    if ($actual -ne [string]$evidence.binary_sha256.($entry.Key)) {
        throw "Binary hash mismatch: $($entry.Key)"
    }
    $binaryCount++
}
$commandRecords = @(
    @('.forge-codex\state\commands\20260830T075931966Z-8af7d831.json', [string]$evidence.recorded_build.command_record_sha256),
    @('.forge-codex\state\commands\20260830T080038415Z-063814c2.json', [string]$evidence.recorded_validation.command_record_sha256)
)
foreach ($record in $commandRecords) {
    $actual = Get-FileSha256 -Path (Join-Path $workspace $record[0])
    if ($actual -ne $record[1]) {
        throw "Command-record hash mismatch: $($record[0])"
    }
}
& (Join-Path $workspace '.forge-codex\instructions\scripts\Validate-NoPython.ps1') -WorkspaceRoot $workspace
& (Join-Path $workspace '.forge-codex\instructions\scripts\Validate-NoAttribution.ps1') -WorkspaceRoot $workspace
& (Join-Path $workspace '.forge-codex\instructions\scripts\Verify-Ledger.ps1') -WorkspaceRoot $workspace
$diffOutput = & git -C $workspace diff --check 2>&1
if ($LASTEXITCODE -ne 0) {
    throw "git diff --check failed: $diffOutput"
}
$changedTextFiles = @(
    '.forge-codex\state\decisions\P16-022-exact-per-user-manager-startup-policy.md',
    '.forge-codex\state\evidence\P16\manager-startup-policy-checkpoint.json',
    'CMakeLists.txt',
    'include\ForgeConductor\Contracts\Contracts.h',
    'include\ForgeConductor\Contracts\IManagerStartupService.h',
    'include\ForgeConductor\Domain\Domain.h',
    'include\ForgeConductor\Domain\ManagerStartupModels.h',
    'include\ForgeConductor\Manager\ManagerStartupTaskPolicy.h',
    'src\Domain\ManagerStartupModels.cpp',
    'src\Manager\ManagerStartupTaskPolicy.cpp',
    'tests\Manager\ManagerStartupTaskPolicyTests.cpp'
)
$strictUtf8 = [Text.UTF8Encoding]::new($false, $true)
foreach ($relative in $changedTextFiles) {
    $bytes = [IO.File]::ReadAllBytes((Join-Path $workspace $relative))
    if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xef -and $bytes[1] -eq 0xbb -and $bytes[2] -eq 0xbf) {
        throw "UTF-8 BOM is forbidden: $relative"
    }
    $text = $strictUtf8.GetString($bytes)
    if ($text -match '(?<!\r)\n' -or $text -match '\r(?!\n)') {
        throw "Non-CRLF line ending: $relative"
    }
    foreach ($line in [regex]::Split($text, '\r\n')) {
        if ($line -match '[ \t]+$') {
            throw "Trailing whitespace: $relative"
        }
    }
}
Write-Output "Source hashes matched: $sourceCount"
Write-Output "Binary hashes matched: $binaryCount"
Write-Output "Command records matched: $($commandRecords.Count)"
Write-Output "Changed text files CRLF UTF-8 no BOM: $($changedTextFiles.Count)"
Write-Output 'git diff --check passed.'
exit 0
